def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                desperate_count += 1
            if opp.get('budget', 0) >= 150:
                rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 8.0))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    high_supply = supply >= 24
    low_supply = supply <= 18
    critical_self = (no_water_days >= 2) or (hp <= 3)
    urgent_self = (no_water_days >= 1) or (hp <= 5)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    if prev_bids:
        sorted_bids = sorted(prev_bids, reverse=True)
        idx = int(min(len(sorted_bids) - 1, max(0, slots - 1)))
        moderate_prev = sorted_bids[int(idx)]

    base = 12.0
    if high_supply:
        base = 9.0
    elif low_supply:
        base = 28.0
    else:
        base = 18.0

    if desperate_count >= 2:
        base += 10.0
    elif desperate_count == 1:
        base += 5.0

    if rich_aggressive >= 2:
        base += 6.0

    if day >= 8:
        base += 6.0

    if critical_self:
        target = max(base + 25.0, moderate_prev + 3.0, 62.0)
    elif urgent_self:
        target = max(base + 10.0, moderate_prev + 2.0, 34.0)
    else:
        if high_supply and highest_prev >= 120:
            target = 7.0
        elif highest_prev >= 160:
            target = 10.0 if hp >= 6 else 58.0
        elif highest_prev >= 110:
            target = 14.0 if hp >= 6 else max(48.0, moderate_prev + 1.5)
        elif moderate_prev > 0:
            target = max(base, moderate_prev + 1.5)
        else:
            target = base

    if slots >= 2 and not urgent_self:
        target -= 4.0
    if slots == 1 and urgent_self:
        target += 8.0

    reserve = 0.0
    if day <= 7:
        reserve = 20.0
    elif day <= 9:
        reserve = 10.0

    cap = budget - reserve
    if critical_self:
        cap = budget
    elif urgent_self:
        cap = max(cap, budget * 0.75)

    if cap < 0:
        cap = budget

    bid = min(target, cap)

    if critical_self and bid < 55.0:
        bid = min(budget, 55.0)
    if urgent_self and bid < 30.0:
        bid = min(budget, 30.0)

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # If we are already in critical condition, bid aggressively to prevent collapse.
    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read only yesterday's immediate trace bids.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine how many full water units are likely available.
    # supply is float; convert to int for indexing-free logic.
    # If supply is near minimum, competition is higher.
    tight_supply = supply <= (MIN_SUPPLY + 2.0)

    # Base bid target: secure water when tight, otherwise bid moderately.
    if tight_supply:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # If yesterday someone was bidding very high, raise slightly to beat them.
    # Eric died with very low bids, implying others avoid starvation; high_prev_bid is a proxy for current intensity.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = max(base, highest_prev_bid * 0.95)

    # If our hp is low, we must spend more.
    if my_hp <= 2:
        base = max(base, DAILY_SALARY * 0.95)
    elif my_hp <= 4:
        base = max(base, DAILY_SALARY * 0.75)

    # Never exceed budget; also cap to avoid burning money when supply is likely sufficient.
    # Slightly undercut highest_prev_bid when not tight.
    if not tight_supply and highest_prev_bid > 0:
        base = min(base, highest_prev_bid * 0.9 + 2.0)

    bid = min(my_budget, max(0.0, base))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0
    max_prev = max(yesterday_bids) if yesterday_bids else 80.0

    if my_status['hp'] < 4:
        return min(my_status['budget'], max_prev + 5.0)

    if day_context['supply'] < WATER_REQ * (len(alive_opponents) + 1):
        return min(my_status['budget'], max_prev + 2.0)

    return min(my_status['budget'], max(avg_bid * 0.9, 30.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])  # Ensure integer
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = my_status['budget']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Collect yesterday's bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            yesterday_bids.append(trace['bid'])

    # Determine aggressive threshold from yesterday
    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
    else:
        max_yesterday = 0.0

    # Water scarcity: number of competitors
    num_alive = len(alive_opponents)
    # Need water if supply is limited (if supply < num_alive * WATER_REQ, competition)
    # Simple heuristic
    if hp <= 4:
        # Urgent need for water
        target_bid = min(budget, max(DAILY_SALARY * 0.9, max_yesterday * 0.95 + 1))
    else:
        # Healthy, try to save
        if max_yesterday >= DAILY_SALARY * 0.8:
            # Others are aggressive, bid conservative
            target_bid = min(budget, DAILY_SALARY * 0.4)
        else:
            # Moderate competition
            target_bid = min(budget, max(DAILY_SALARY * 0.5, max_yesterday * 0.8))

    # Ensure we don't exceed budget
    return min(budget, target_bid)
